import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cpp_src = r"""
#include <torch/extension.h>
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_fp16.h>
#include <mma.h>
#include <math.h>
using namespace nvcuda;
__device__ __forceinline__ float warpReduceSum(float v) {
    for (int offset = 16; offset > 0; offset >>= 1)
        v += __shfl_xor_sync(0xffffffffu, v, offset);
    return v;
}
__device__ __forceinline__ float warpReduceMax(float v) {
    for (int offset = 16; offset > 0; offset >>= 1)
        v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, offset));
    return v;
}
// Tensor-core (WMMA) flash-style SDPA. One CTA computes a 32-row query tile for
// one (batch*head): scores = Q_tile @ K^T via mma (K-dim tiled, fp32 accum),
// warp-cooperative row softmax, then O_tile = P @ V via mma (fp32 accum).
template <int NT>  // S = 64 * NT
__global__ void sdpa_kernel(const __half* __restrict__ Q,
                            const __half* __restrict__ K,
                            const __half* __restrict__ V,
                            __half* __restrict__ O,
                            int S, int D, float scale) {
    constexpr int MROWS = 32;
    constexpr int QK_STRIDE = 72;
    constexpr int V_STRIDE = 128;
    constexpr int O_STRIDE = 128;
    extern __shared__ char smem_raw[];
    const int SS = S + 4;
    const int PS = S;
    float*  scores = reinterpret_cast<float*>(smem_raw);
    __half* q_s = reinterpret_cast<__half*>(smem_raw + (size_t)MROWS * SS * sizeof(float));
    __half* k_s = q_s + (size_t)MROWS * QK_STRIDE;
    __half* v_s = reinterpret_cast<__half*>(smem_raw);
    float*  o_s = reinterpret_cast<float*>(smem_raw + (size_t)S * V_STRIDE * sizeof(__half));
    __half* p_s = reinterpret_cast<__half*>(smem_raw + (size_t)S * V_STRIDE * sizeof(__half) + (size_t)MROWS * O_STRIDE * sizeof(float));
    const int bh = blockIdx.y;
    const int q0 = blockIdx.x * MROWS;
    const long base = (long)bh * (long)S * (long)D;
    const __half* Qg = Q + base;
    const __half* Kg = K + base;
    const __half* Vg = V + base;
    __half* Og = O + base;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int warp_m = warp & 1;
    const int warp_n = warp >> 1;
    // Phase 1: scores = Q_tile @ K^T (tensor cores, fp32 accumulation).
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[NT];
    #pragma unroll
    for (int t = 0; t < NT; ++t) wmma::fill_fragment(acc[t], 0.0f);
    for (int kc = 0; kc < D; kc += 64) {
        {
            const int r = tid >> 3;
            const int c8 = (tid & 7) << 3;
            *reinterpret_cast<uint4*>(q_s + r * QK_STRIDE + c8) =
                *reinterpret_cast<const uint4*>(Qg + (long)(q0 + r) * D + kc + c8);
        }
        for (int idx = tid; idx < S * 8; idx += 256) {
            const int r = idx >> 3;
            const int c8 = (idx & 7) << 3;
            *reinterpret_cast<uint4*>(k_s + r * QK_STRIDE + c8) =
                *reinterpret_cast<const uint4*>(Kg + (long)r * D + kc + c8);
        }
        __syncthreads();
        #pragma unroll
        for (int ks = 0; ks < 4; ++ks) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
            wmma::load_matrix_sync(a, q_s + (warp_m * 16) * QK_STRIDE + ks * 16, QK_STRIDE);
            #pragma unroll
            for (int t = 0; t < NT; ++t) {
                wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::col_major> b;
                wmma::load_matrix_sync(b, k_s + (warp_n * (NT * 16) + t * 16) * QK_STRIDE + ks * 16, QK_STRIDE);
                wmma::mma_sync(acc[t], a, b, acc[t]);
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int t = 0; t < NT; ++t)
        wmma::store_matrix_sync(scores + (warp_m * 16) * SS + warp_n * (NT * 16) + t * 16,
                                acc[t], SS, wmma::mem_row_major);
    __syncthreads();
    // Safe row softmax: 8 warps x 4 rows; normalized P stored as fp16 for mma.
    #pragma unroll
    for (int i = 0; i < MROWS / 8; ++i) {
        const int r = warp * (MROWS / 8) + i;
        const float* srow = scores + r * SS;
        float vals[2 * NT];
        float mx = -1e30f;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi) {
            vals[vi] = srow[lane + vi * 32] * scale;
            mx = fmaxf(mx, vals[vi]);
        }
        mx = warpReduceMax(mx);
        float s = 0.0f;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi) {
            vals[vi] = __expf(vals[vi] - mx);
            s += vals[vi];
        }
        s = warpReduceSum(s);
        const float inv = 1.0f / s;
        __half* prow = p_s + r * PS;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi)
            prow[lane + vi * 32] = __float2half(vals[vi] * inv);
    }
    __syncthreads();
    // Phase 2: O_tile = P @ V (tensor cores, fp32 accumulation), D tiled by 128.
    for (int nc = 0; nc < D; nc += 128) {
        for (int idx = tid; idx < S * 16; idx += 256) {
            const int r = idx >> 4;
            const int c8 = (idx & 15) << 3;
            *reinterpret_cast<uint4*>(v_s + r * V_STRIDE + c8) =
                *reinterpret_cast<const uint4*>(Vg + (long)r * D + nc + c8);
        }
        __syncthreads();
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc0, oacc1;
        wmma::fill_fragment(oacc0, 0.0f);
        wmma::fill_fragment(oacc1, 0.0f);
        for (int kk = 0; kk < S; kk += 16) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
            wmma::load_matrix_sync(a, p_s + (warp_m * 16) * PS + kk, PS);
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b0, b1;
            wmma::load_matrix_sync(b0, v_s + kk * V_STRIDE + warp_n * 32, V_STRIDE);
            wmma::load_matrix_sync(b1, v_s + kk * V_STRIDE + warp_n * 32 + 16, V_STRIDE);
            wmma::mma_sync(oacc0, a, b0, oacc0);
            wmma::mma_sync(oacc1, a, b1, oacc1);
        }
        wmma::store_matrix_sync(o_s + (warp_m * 16) * O_STRIDE + warp_n * 32, oacc0, O_STRIDE, wmma::mem_row_major);
        wmma::store_matrix_sync(o_s + (warp_m * 16) * O_STRIDE + warp_n * 32 + 16, oacc1, O_STRIDE, wmma::mem_row_major);
        __syncthreads();
        for (int idx = tid; idx < MROWS * 64; idx += 256) {
            const int r = idx >> 6;
            const int c2 = (idx & 63) << 1;
            __half2 hv;
            hv.x = __float2half(o_s[r * O_STRIDE + c2]);
            hv.y = __float2half(o_s[r * O_STRIDE + c2 + 1]);
            *reinterpret_cast<__half2*>(Og + (long)(q0 + r) * D + nc + c2) = hv;
        }
        __syncthreads();
    }
}
template <int NT>
static void sdpa_launch(const __half* q, const __half* k, const __half* v, __half* o,
                        int S, int D, float scale, dim3 grid, size_t smem, cudaStream_t stream) {
    static bool configured = false;
    if (!configured) {
        cudaError_t attr_err = cudaFuncSetAttribute(sdpa_kernel<NT>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
        TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
        configured = true;
    }
    sdpa_kernel<NT><<<grid, 256, smem, stream>>>(q, k, v, o, S, D, scale);
}
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q/K/V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf, "expected float16 inputs");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "inputs must be contiguous");
    const int B = Q.size(0);
    const int H = Q.size(1);
    const int S = Q.size(2);
    const int D = Q.size(3);
    TORCH_CHECK(S % 64 == 0 && S <= 256, "S must be a multiple of 64 up to 256");
    TORCH_CHECK(D % 128 == 0, "D must be a multiple of 128");
    auto O = torch::empty_like(Q);
    dim3 grid(S / 32, B * H);
    const size_t smem_p1 = (size_t)32 * (S + 4) * sizeof(float) + (size_t)32 * 72 * sizeof(__half) + (size_t)S * 72 * sizeof(__half);
    const size_t smem_p2 = (size_t)S * 128 * sizeof(__half) + (size_t)32 * 128 * sizeof(float) + (size_t)32 * S * sizeof(__half);
    const size_t smem = std::max(smem_p1, smem_p2);
    const float scale = 1.0f / sqrtf((float)D);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const __half* q = reinterpret_cast<const __half*>(Q.data_ptr<at::Half>());
    const __half* k = reinterpret_cast<const __half*>(K.data_ptr<at::Half>());
    const __half* v = reinterpret_cast<const __half*>(V.data_ptr<at::Half>());
    __half* o = reinterpret_cast<__half*>(O.data_ptr<at::Half>());
    switch (S / 64) {
        case 1: sdpa_launch<1>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 2: sdpa_launch<2>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 3: sdpa_launch<3>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 4: sdpa_launch<4>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        default: TORCH_CHECK(false, "unsupported sequence length");
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return O;
}
"""
_sdpa = load_inline(
    name="sdpa_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sdpa_forward"],
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return _sdpa.sdpa_forward(Q, K, V)
batch_size = 2
num_heads = 32
sequence_length = 256
embedding_dimension = 1024
def get_inputs():
    Q = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    K = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    V = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    return [Q, K, V]
def get_init_inputs():
    return []

