    // Safe row softmax: 8 warps x 4 rows; normalized P stored as fp16 for mma.
    #pragma unroll
    for (int i = 0; i < MROWS / 8; ++i) {
        const int r = warp * (MROWS / 8) + i;
        const float* srow = scores + r * SS;
        float vals[2 * NT];
        float mx = -1e30f;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi) {
            vals[vi] = srow[lane + vi * 32] * scale;
            mx = fmaxf(mx, vals[vi]);
        }
        mx = warpReduceMax(mx);
        float s = 0.0f;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi) {
            vals[vi] = __expf(vals[vi] - mx);
            s += vals[vi];
        }
        s = warpReduceSum(s);
        const float inv = 1.0f / s;
        __half* prow = p_s + r * PS;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi)
            prow[lane + vi * 32] = __float2half(vals[vi] * inv);
    }
    __syncthreads();
    // Phase 2: O_tile = P @ V (tensor cores, fp32 accumulation), D tiled by 128.
    for (int nc = 0; nc < D; nc += 128) {
        for (int idx = tid; idx < S * 16; idx += 256) {
            const int r = idx >> 4;
            const int c8 = (idx & 15) << 3;
            *reinterpret_cast<uint4*>(v_s + r * V_STRIDE + c8) =
                *reinterpret_cast<const uint4*>(Vg + (long)r * D + nc + c8);
        }
        __syncthreads();
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc0, oacc1;
        wmma::fill_fragment(oacc0, 0.0f);
        wmma::fill_fragment(oacc1, 0.0f);
        for (int kk = 0; kk < S; kk += 16) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
            wmma::load_matrix_sync(a, p_s + (warp_m * 16) * PS + kk, PS);
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b0, b1;
            wmma::load_matrix_sync(b0, v_s + kk * V_STRIDE + warp_n * 32, V_STRIDE);
            wmma::load_matrix_sync(b1, v_s + kk * V_STRIDE + warp_n * 32 + 16, V_STRIDE);
            wmma::mma_sync(oacc0, a, b0, oacc0);
            wmma::mma_sync(oacc1, a, b1, oacc1);
        }
        wmma::store_matrix_sync(o_s + (warp_m * 16) * O_STRIDE + warp_n * 32, oacc0, O_STRIDE, wmma::mem_row_major);
        wmma::store_matrix_sync(o_s + (warp_m * 16) * O_STRIDE + warp_n * 32 + 16, oacc1, O_STRIDE, wmma::mem_row_major);
        __syncthreads();
        for (int idx = tid; idx < MROWS * 64; idx += 256) {
            const int r = idx >> 6;
            const int c2 = (idx & 63) << 1;
            __half2 hv;
            hv.x = __float2half(o_s[r * O_STRIDE + c2]);
            hv.y = __float2half(o_s[r * O_STRIDE + c2 + 1]);
            *reinterpret_cast<__half2*>(Og + (long)(q0 + r) * D + nc + c2) = hv;
        }
        __syncthreads();
    }
}
template <int NT>
static void sdpa_launch(const __half* q, const __half* k, const __half* v, __half* o,
                        int S, int D, float scale, dim3 grid, size_t smem, cudaStream_t stream) {
    static bool configured = false;
    if (!configured) {
        cudaError_t attr_err = cudaFuncSetAttribute(sdpa_kernel<NT>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
        TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
        configured = true;
    }
    sdpa_kernel<NT><<<grid, 256, smem, stream>>>(q, k, v, o, S, D, scale);
}
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q/K/V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf, "expected float16 inputs");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "inputs must be contiguous");
    const int B = Q.size(0);
    const int H = Q.size(1);
    const int S = Q.size(2);
    const int D = Q.size(3);
    TORCH_CHECK(S % 64 == 0 && S <= 256, "S must be a multiple of 64 up to 256");
    TORCH_CHECK(D % 128 == 0, "D must be a multiple of 128");
    auto O = torch::empty_like(Q);
    dim3 grid(S / 32, B * H);
    const size_t smem_p1 = (size_t)32 * (S + 4) * sizeof(float) + (size_t)32 * 72 * sizeof(__half) + (size_t)S * 72 * sizeof(__half);
    const size_t smem_p2 = (size_t)S * 128 * sizeof(__half) + (size_t)32 * 128 * sizeof(float) + (size_t)32 * S * sizeof(__half);
    const size_t smem = std::max(smem_p1, smem_p2);
    const float scale = 1.0f / sqrtf((float)D);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const __half* q = reinterpret_cast<const __half*>(Q.data_ptr<at::Half>());
    const __half* k = reinterpret_cast<const __half*>(K.data_ptr<at::Half>());
    const __half* v = reinterpret_cast<const __half*>(V.data_ptr<at::Half>());
    __half* o = reinterpret_cast<__half*>(O.data_ptr<at::Half>());
    switch (S / 64) {
        case 1: sdpa_launch<1>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 2: sdpa_launch<2>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 3: sdpa_launch<3>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 4: sdpa_launch<4>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        default: TORCH_CHECK(false, "unsupported sequence length");
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return O;
}
